import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import Layout from '../../components/Layout';
import StatusBadge from '../../components/StatusBadge';
import API from '../../api/axios';

export default function CustomerOrderDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [order, setOrder] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    API.get(`/customer/orders/${id}`)
      .then(({ data }) => setOrder(data.order))
      .catch(() => navigate('/customer/orders'))
      .finally(() => setLoading(false));
  }, [id]); // eslint-disable-line

  if (loading) return <Layout title="Order Detail"><div className="spinner" /></Layout>;
  if (!order) return <Layout title="Order Detail"><div className="alert alert-error">Order not found.</div></Layout>;

  return (
    <Layout title={`Quotation — ${order.orderNumber}`}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '1.5rem', flexWrap: 'wrap' }}>
        <button className="btn btn-ghost btn-sm" onClick={() => navigate('/customer/orders')}>← My Orders</button>
        <h1 className="page-title" style={{ margin: 0 }}>{order.orderNumber}</h1>
        <StatusBadge status={order.status} />
      </div>

      <div className="grid-2" style={{ alignItems: 'start' }}>

        {/* ── Left column ── */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>

          {/* Quotation card — full inline view */}
          <div className="card" style={{ padding: 0, overflow: 'hidden' }}>
            {/* Quotation header */}
            <div style={{
              background: 'linear-gradient(135deg, #1e40af, #3b82f6)',
              color: '#fff', padding: '1.25rem 1.5rem',
              display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', flexWrap: 'wrap', gap: '0.5rem'
            }}>
              <div>
                <div style={{ fontSize: '0.75rem', opacity: 0.8, textTransform: 'uppercase', letterSpacing: '0.05em' }}>Quotation</div>
                <div style={{ fontSize: '1.25rem', fontWeight: 700 }}>{order.orderNumber}</div>
                <div style={{ fontSize: '0.8rem', opacity: 0.85, marginTop: '0.2rem' }}>
                  {new Date(order.createdAt).toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })}
                </div>
              </div>
              <div style={{ textAlign: 'right' }}>
                <div style={{ fontSize: '0.75rem', opacity: 0.8 }}>Store</div>
                <div style={{ fontWeight: 600 }}>{order.storeName}</div>
              </div>
            </div>

            {/* Customer info strip */}
            <div style={{ padding: '0.85rem 1.5rem', background: '#f8fafc', borderBottom: '1px solid #e5e7eb', display: 'flex', gap: '2rem', flexWrap: 'wrap', fontSize: '0.8rem' }}>
              <div><span style={{ color: '#6b7280' }}>Customer: </span><strong>{order.customerName}</strong></div>
              <div><span style={{ color: '#6b7280' }}>Phone: </span>{order.customerPhone}</div>
              {order.customerEmail && <div><span style={{ color: '#6b7280' }}>Email: </span>{order.customerEmail}</div>}
              {order.deliveryAddress && <div><span style={{ color: '#6b7280' }}>Address: </span>{order.deliveryAddress}</div>}
            </div>

            {/* Items table */}
            <table>
              <thead>
                <tr>
                  <th>#</th>
                  <th>Item</th>
                  <th>Qty</th>
                  <th>Unit Price</th>
                  <th>Subtotal</th>
                </tr>
              </thead>
              <tbody>
                {order.items.map((item, i) => (
                  <tr key={i}>
                    <td style={{ color: '#9ca3af', fontSize: '0.8rem' }}>{i + 1}</td>
                    <td>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                        {item.image ? (
                          <img src={`/uploads/${item.image}`} alt="" style={{ width: 36, height: 36, borderRadius: '0.35rem', objectFit: 'cover', flexShrink: 0 }} />
                        ) : (
                          <div style={{ width: 36, height: 36, background: '#f3f4f6', borderRadius: '0.35rem', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#9ca3af', fontSize: '1rem', flexShrink: 0 }}>📦</div>
                        )}
                        <span style={{ fontWeight: 500, fontSize: '0.875rem' }}>{item.name}</span>
                      </div>
                    </td>
                    <td style={{ fontSize: '0.875rem' }}>{item.quantity} <span style={{ color: '#9ca3af', fontSize: '0.75rem' }}>{item.unit}</span></td>
                    <td style={{ fontSize: '0.875rem' }}>{item.price?.toFixed(2)}</td>
                    <td style={{ fontWeight: 700, fontSize: '0.875rem', color: '#2563eb' }}>{item.subtotal?.toFixed(2)}</td>
                  </tr>
                ))}
              </tbody>
            </table>

            {/* Totals */}
            <div style={{ padding: '1rem 1.5rem', borderTop: '1px solid #f3f4f6', background: '#fafafa' }}>
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: '0.3rem', fontSize: '0.875rem' }}>
                <div style={{ display: 'flex', gap: '2rem' }}>
                  <span style={{ color: '#6b7280' }}>Subtotal</span>
                  <strong style={{ minWidth: 80, textAlign: 'right' }}>{order.subtotal?.toFixed(2)}</strong>
                </div>
                {order.tax > 0 && (
                  <div style={{ display: 'flex', gap: '2rem' }}>
                    <span style={{ color: '#6b7280' }}>Tax</span>
                    <strong style={{ minWidth: 80, textAlign: 'right' }}>{order.tax?.toFixed(2)}</strong>
                  </div>
                )}
                {order.discount > 0 && (
                  <div style={{ display: 'flex', gap: '2rem' }}>
                    <span style={{ color: '#6b7280' }}>Discount</span>
                    <strong style={{ minWidth: 80, textAlign: 'right', color: '#16a34a' }}>-{order.discount?.toFixed(2)}</strong>
                  </div>
                )}
                <div style={{ display: 'flex', gap: '2rem', borderTop: '2px solid #2563eb', paddingTop: '0.5rem', marginTop: '0.25rem' }}>
                  <span style={{ fontWeight: 700, fontSize: '1rem' }}>Total</span>
                  <strong style={{ minWidth: 80, textAlign: 'right', fontSize: '1.2rem', color: '#2563eb' }}>{order.total?.toFixed(2)}</strong>
                </div>
              </div>
            </div>

            {/* Notes */}
            {(order.customerNote || order.ownerNote) && (
              <div style={{ padding: '0.85rem 1.5rem', borderTop: '1px solid #f3f4f6' }}>
                {order.customerNote && (
                  <div style={{ marginBottom: '0.5rem' }}>
                    <span style={{ fontSize: '0.75rem', color: '#6b7280', fontWeight: 600 }}>Your note: </span>
                    <span style={{ fontSize: '0.8rem' }}>{order.customerNote}</span>
                  </div>
                )}
                {order.ownerNote && (
                  <div style={{ padding: '0.6rem 0.85rem', background: '#f0fdf4', borderRadius: '0.4rem', borderLeft: '3px solid #16a34a' }}>
                    <span style={{ fontSize: '0.75rem', color: '#166534', fontWeight: 600 }}>Store note: </span>
                    <span style={{ fontSize: '0.8rem', color: '#166534' }}>{order.ownerNote}</span>
                  </div>
                )}
              </div>
            )}

            {/* Footer */}
            <div style={{ padding: '0.75rem 1.5rem', background: '#f8fafc', borderTop: '1px solid #f3f4f6', textAlign: 'center', fontSize: '0.78rem', color: '#9ca3af' }}>
              Thank you for your order! This quotation is valid and can be downloaded below.
            </div>
          </div>
        </div>

        {/* ── Right column ── */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>

          {/* Order info */}
          <div className="card">
            <h3 style={{ fontWeight: 700, marginBottom: '1rem', fontSize: '0.95rem' }}>Order Details</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '0.6rem', fontSize: '0.875rem' }}>
              {[
                ['Order #', order.orderNumber],
                ['Store', order.storeName],
                ['Items', order.items?.length],
                ['Date', new Date(order.createdAt).toLocaleDateString()],
              ].map(([label, value]) => (
                <div key={label} style={{ display: 'flex', justifyContent: 'space-between', paddingBottom: '0.6rem', borderBottom: '1px solid #f3f4f6' }}>
                  <span style={{ color: '#6b7280' }}>{label}</span>
                  <span style={{ fontWeight: 500 }}>{value}</span>
                </div>
              ))}
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <span style={{ color: '#6b7280' }}>Status</span>
                <StatusBadge status={order.status} />
              </div>
            </div>
          </div>

          {/* Download quotation */}
          <div className="card">
            <h3 style={{ fontWeight: 700, marginBottom: '0.5rem', fontSize: '0.95rem' }}>📥 Download Quotation</h3>
            <p style={{ fontSize: '0.8rem', color: '#6b7280', marginBottom: '1rem', lineHeight: 1.5 }}>
              Save your quotation as a PDF or Excel file for your records or to share with others.
            </p>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '0.6rem' }}>
              <a
                href={`/api/customer/orders/${id}/quotation/pdf`}
                target="_blank"
                rel="noreferrer"
                className="btn btn-primary"
                style={{ justifyContent: 'center' }}
              >
                📄 Download PDF
              </a>
              <a
                href={`/api/customer/orders/${id}/quotation/excel`}
                target="_blank"
                rel="noreferrer"
                className="btn btn-outline"
                style={{ justifyContent: 'center', color: '#16a34a', borderColor: '#16a34a' }}
              >
                📊 Download Excel
              </a>
            </div>
          </div>

          {/* Invoice (if store sent one) */}
          {order.invoicePdfPath && (
            <div className="card">
              <h3 style={{ fontWeight: 700, marginBottom: '0.5rem', fontSize: '0.95rem' }}>🧾 Invoice</h3>
              <p style={{ fontSize: '0.8rem', color: '#6b7280', marginBottom: '1rem' }}>
                The store has confirmed your order and issued an invoice.
              </p>
              <a
                href={`/uploads/docs/${order.invoicePdfPath.split(/[\\/]/).pop()}`}
                target="_blank"
                rel="noreferrer"
                className="btn btn-success"
                style={{ justifyContent: 'center', width: '100%' }}
              >
                📄 Download Invoice PDF
              </a>
            </div>
          )}

          {/* Status timeline */}
          <div className="card">
            <h3 style={{ fontWeight: 700, marginBottom: '1rem', fontSize: '0.95rem' }}>Order Status</h3>
            {[
              { key: 'pending', label: 'Order Placed', icon: '🛒' },
              { key: 'confirmed', label: 'Confirmed by Store', icon: '✅' },
              { key: 'processing', label: 'Processing', icon: '⚙️' },
              { key: 'completed', label: 'Completed', icon: '🎉' },
            ].map((step) => {
              const statuses = ['pending', 'confirmed', 'processing', 'completed'];
              const currentIdx = statuses.indexOf(order.status);
              const stepIdx = statuses.indexOf(step.key);
              const isDone = currentIdx >= stepIdx && order.status !== 'cancelled';
              const isCurrent = order.status === step.key;
              return (
                <div key={step.key} style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', padding: '0.5rem 0', opacity: isDone ? 1 : 0.35 }}>
                  <div style={{
                    width: 32, height: 32, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '0.9rem', flexShrink: 0,
                    background: isCurrent ? '#dbeafe' : isDone ? '#dcfce7' : '#f3f4f6',
                    border: isCurrent ? '2px solid #2563eb' : isDone ? '2px solid #16a34a' : '2px solid #e5e7eb',
                  }}>
                    {step.icon}
                  </div>
                  <span style={{ fontSize: '0.875rem', fontWeight: isCurrent ? 600 : 400, color: isCurrent ? '#1e40af' : '#374151' }}>
                    {step.label}
                  </span>
                  {isCurrent && <span className="badge badge-blue" style={{ fontSize: '0.7rem', marginLeft: 'auto' }}>Current</span>}
                  {isDone && !isCurrent && <span style={{ marginLeft: 'auto', color: '#16a34a', fontSize: '0.8rem' }}>✓</span>}
                </div>
              );
            })}
            {order.status === 'cancelled' && (
              <div style={{ marginTop: '0.5rem', padding: '0.6rem 0.85rem', background: '#fee2e2', borderRadius: '0.4rem', fontSize: '0.8rem', color: '#991b1b' }}>
                ❌ This order was cancelled.
              </div>
            )}
          </div>

        </div>
      </div>
    </Layout>
  );
}
